local R=dofile('tests/kernel_world_harness.lua')
local H,n=R.H,0
local function case(name,fn)R.clientCase(name,fn);n=n+1 end
case('default frame',function(r)assert(r.tick()==0);assert(#r.trace==5)end)
case('default periodic',function(r)assert(r.tick(2)==10000)end)
case('non-table fallback',function(r)r.value='bad';r.tick();r.tick(2)end)
case('first revision applies',function(r)r.value=H.copy(r.config.Density.Defaults);r.value.revision=1;r.tick()end)
case('same revision no reapply',function(r)r.value=H.copy(r.config.Density.Defaults);r.value.revision=1;r.tick();r.trace={};r.tick();assert(#r.trace==5)end)
case('changed revision reapplies',function(r)r.value=H.copy(r.config.Density.Defaults);r.value.revision=1;r.tick();r.trace={};r.value.revision=2;r.tick();assert(#r.trace>5)end)
case('disabled still forces zero',function(r)r.value={enabled=false,revision=1};r.tick();assert(#r.trace==5);for _,x in ipairs(r.trace)do assert(x.args[1]==0)end end)
case('disable all no population',function(r)r.value=H.copy(r.config.Density.Defaults);r.value.disableAll=true;r.value.revision=1;r.tick()end)
case('raw client values unclamped',function(r)r.value={enabled=true,values={parked=9,peds=-4,vehicle='0.6',scenario='bad'},revision=1};r.tick()end)
case('missing budget fallback',function(r)r.value={enabled=true,revision=1};r.tick()end)
case('generator bbox',function(r)r.value={enabled=true,revision=1,generatorAreas={{distance='4',coords={x=1,y=2,z=3}},{distance=-1}}};r.tick()end)
case('malformed area inherited error',function(r)r.value={enabled=true,revision=1,generatorAreas={false}};assert(not pcall(r.tick))end)
case('blacklist',function(r)r.value={enabled=true,revision=1,blacklist={enabled=true,models={'RHINO'},scenarioTypes={'POLICE'},scenarioGroups={'PLANES'}}};r.tick()end)
case('dispatch disabled',function(r)r.value={enabled=true,revision=1,disableDispatchServices=true};r.tick()end)
case('removal never restores inherited',function(r)r.value=H.copy(r.config.Density.Defaults);r.value.revision=1;r.tick();r.trace={};r.value={enabled=false,revision=2};r.tick();assert(#r.trace==5)end)
case('periodic always reapplies',function(r)r.tick(2);local n=#r.trace;r.tick(2);assert(#r.trace==2*n)end)
case('same revision mutation waits periodic',function(r)r.value={enabled=true,revision=1};r.tick();r.trace={};r.value.disableDispatchServices=true;r.tick();assert(#r.trace==5);r.tick(2);assert(#r.trace>5)end)
print('PASS world density client differentials '..n)
